function Brand(){return <div className="brand-mark"><span className="brand-icon"><Activity size={19} strokeWidth={2.8}/></span><span>football<span className="brand-light">forum</span><i>.</i></span></div>}
function Avatar({initials,color='navy',size='normal',src,alt='User profile'}){return <div className={`avatar avatar-${color} avatar-${size}${src?' avatar-photo':''}`} aria-label={alt}>{src?<img src={src} alt={alt} loading="lazy" onError={e=>{e.currentTarget.style.display='none';e.currentTarget.parentElement.classList.remove('avatar-photo')}}/>:initials}</div>}
function LevelInsignia({level=1,compact=false}){return <span className={`level-insignia level-insignia-${level}${compact?' level-insignia-compact':''}`} title={levels[level-1]?.name||'Football Forum level'} aria-label={levels[level-1]?.name||'Football Forum level'}><svg viewBox="0 0 40 40" aria-hidden="true" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">{level===1?<g><path d="M9 25 17 9l8 4 6 9-4 4-7-2-5 4z"/><path d="m17 9-2 9 6 6m4-11-4 11m-6-6-7 7 2 5 8-2 4-5"/><path d="m10 30 6-1m9-16 4-4"/></g>:level===2?<g><circle cx="20" cy="20" r="14"/><path d="m20 11 6 4-2 7h-8l-2-7zM20 11V6m6 9 7-2M24 22l5 7M16 22l-5 7m3-14-7-2m9 18 4 4m-4-10-1 8m8-8 1 8"/></g>:level===3?<g><path d="M7 33V8h26v25M7 13h26M12 33V18h16v15"/><path d="M16 8V4h8v4M20 18v15m-8-8h16"/><circle cx="20" cy="14" r="2"/></g>:level===4?<g><path d="M8 13h24v14H8z"/><path d="m8 16-4 2 4 3m24-5 4 2-4 3M13 13v14m14-14v14"/><path d="m16 18 4-3 4 3-4 5z"/></g>:level===5?<g><path d="M8 26 15 9l7 3 3 7 6 4-3 6-8-2-5 4-7-5z"/><path d="m15 9-1 10 6 7m2-14-2 14m5-7 7-3M9 26l7-1m5 2 7 2"/><path d="M11 7 8 4m20 4 4-4"/><path d="M13 34h15"/></g>:<g><path d="m20 4 4.5 9 10 1.5-7.2 7 1.7 10-9-4.8-9 4.8 1.7-10-7.2-7L15.5 13z"/><circle cx="20" cy="20" r="5"/><path d="m20 15 2 3-2 4-2-4zM15 18l3 1m4 0 3-1m-7 5-2 3m6-3 2 3"/></g>}</svg></span>}
function Crest({club,size='normal'}){return <span className={`club-crest crest-${size}`} style={{'--club':club.color}}><img src={club.logo} alt={club.name+' crest'} loading="lazy" onError={e=>{e.currentTarget.style.display='none';e.currentTarget.nextSibling.style.display='grid'}}/><span className="crest-fallback">{club.letter}</span></span>}
