  const [page,setPage]=useState('Home'),[activeTopic,setActiveTopic]=useState('For you'),[liked,setLiked]=useState([]),[saved,setSaved]=useState([]),[composerImage,setComposerImage]=useState(''),[composerImageName,setComposerImageName]=useState(''),[following,setFollowing]=useState([]),[joined,setJoined]=useState(['Arsenal']),[showComposer,setShowComposer]=useState(false),[draft,setDraft]=useState(''),[mobileMenu,setMobileMenu]=useState(false),[notice,setNotice]=useState(''),[query,setQuery]=useState(''),[selectedClub,setSelectedClub]=useState('Arsenal'),[selectedPost,setSelectedPost]=useState(null),[reply,setReply]=useState(''),[register,setRegister]=useState(false),[regClub,setRegClub]=useState('Arsenal'),[regName,setRegName]=useState(''),[regEmail,setRegEmail]=useState(''),[regTerms,setRegTerms]=useState(false),[poll,setPoll]=useState(''),[reported,setReported]=useState([]),[notificationRead,setNotificationRead]=useState(false),[arenaDraft,setArenaDraft]=useState(''),[selectedArenaMatch,setSelectedArenaMatch]=useState(null),[arenaMessages,setArenaMessages]=useState({'arsenal-city':[{id:1,initials:'JM',name:'James M.',club:'Arsenal',time:'Now',text:'If Arsenal control the midfield early, City will have to work for every inch. But leave space behind and Haaland will punish it.'},{id:2,initials:'TO',name:'Tunde O.',club:'Manchester United',time:'Now',text:'This is exactly why matchday banter needs one room 😂 One good chance and everybody suddenly becomes a tactical expert.'},{id:3,initials:'AK',name:'Ada K.',club:'Chelsea',time:'Now',text:'I’m here for the chaos. Someone tell me which defence is giving us the first gift.'}],'liverpool-chelsea':[{id:11,initials:'LF',name:'Liam F.',club:'Liverpool',time:'Now',text:'The first goal changes everything in this one. Press high early and make them uncomfortable.'},{id:12,initials:'CB',name:'Chloe B.',club:'Chelsea',time:'Now',text:'Chelsea need to be brave on the ball. Sitting back for 90 minutes is asking for trouble.'}],'barcelona-madrid':[{id:21,initials:'MP',name:'Marta P.',club:'Barcelona',time:'Now',text:'El Clásico always comes down to who wins the midfield battles.'},{id:22,initials:'RM',name:'Rafa M.',club:'Real Madrid',time:'Now',text:'Big-game players show up in moments like these. Let’s see who handles the pressure.'}]});
 const notify=(message)=>{setNotice(message);window.setTimeout(()=>setNotice(''),2800)};
 const composerPrompts=['What’s on your football mind?','Drop your matchday take.','Who are you backing?'];
 useEffect(()=>{const target=composerPrompts[promptIndex];let delay=promptDeleting?34:62;if(!promptDeleting&&composerPrompt===target)delay=1500;else if(promptDeleting&&composerPrompt==='')delay=250;const timer=window.setTimeout(()=>{if(!promptDeleting&&composerPrompt===target){setPromptDeleting(true);return}if(promptDeleting&&composerPrompt===''){setPromptDeleting(false);setPromptIndex(i=>(i+1)%composerPrompts.length);return}setComposerPrompt(promptDeleting?target.slice(0,composerPrompt.length-1):target.slice(0,composerPrompt.length+1))},delay);return()=>window.clearTimeout(timer)},[composerPrompt,promptDeleting,promptIndex]);
 const fixtureCarouselRef=useRef(null);
 useEffect(()=>{if(page!=='Home')return;const rail=fixtureCarouselRef.current;if(!rail)return;let paused=false;const pause=()=>{paused=true};const resume=()=>{paused=false};rail.addEventListener('pointerenter',pause);rail.addEventListener('pointerleave',resume);rail.addEventListener('focusin',pause);rail.addEventListener('focusout',resume);const motion=window.matchMedia('(prefers-reduced-motion: reduce)');if(motion.matches)return()=>{rail.removeEventListener('pointerenter',pause);rail.removeEventListener('pointerleave',resume);rail.removeEventListener('focusin',pause);rail.removeEventListener('focusout',resume)};const timer=window.setInterval(()=>{if(paused||!rail.isConnected)return;const max=rail.scrollWidth-rail.clientWidth;if(max<=8)return;if(rail.scrollLeft>=max-8){rail.scrollTo({left:0,behavior:'smooth'});return}const card=rail.querySelector('.game-arena-fixture');rail.scrollBy({left:Math.max(180,(card?.getBoundingClientRect().width||220)+10),behavior:'smooth'});},4200);return()=>{window.clearInterval(timer);rail.removeEventListener('pointerenter',pause);rail.removeEventListener('pointerleave',resume);rail.removeEventListener('focusin',pause);rail.removeEventListener('focusout',resume)}},[page]);
