 const visiblePosts=posts.filter(p=>activeTopic==='Following'?following.includes(p.id)||p.id===1:activeTopic==='Transfers'?p.tag==='TRANSFERS':activeTopic==='Tactics'?p.tag==='TACTICS':activeTopic==='Matchday'?p.club==='General football'||p.tag==='DEBATE':true);
 const navigationStackRef=useRef([]);
 const restoreRoute=(route)=>{setPage(route.page||'Home');setSelectedPost(route.selectedPost||null);setSelectedClub(route.selectedClub||'Arsenal');setSelectedArenaMatch(route.selectedArenaMatch||null);setMobileMenu(false);window.setTimeout(()=>window.scrollTo({top:route.scrollY||0,behavior:'auto'}),0)};
 useEffect(()=>{if(!window.history.state?.footballForum)window.history.replaceState({footballForum:true},'');const onPopState=()=>{const previous=navigationStackRef.current.pop();if(previous){restoreRoute(previous)}else{setPage('Home');setSelectedPost(null);setMobileMenu(false);window.scrollTo({top:0,behavior:'auto'})}};window.addEventListener('popstate',onPopState);return()=>window.removeEventListener('popstate',onPopState)},[]);
 const go=(name)=>{navigationStackRef.current.push({page,selectedPost,selectedClub,selectedArenaMatch,scrollY:window.scrollY});window.history.pushState({footballForum:true,page:name},'');if(name==='Matchday Arena')setSelectedArenaMatch(null);setPage(name);setMobileMenu(false);if(name!=='Discussion')setSelectedPost(null);window.scrollTo({top:0,behavior:'smooth'})};
 const goBack=()=>{if(navigationStackRef.current.length>0)window.history.back();else go('Home')};
